//! Which event next, previous, an index and a cue pick, against upstream's own
//! runtime.utils and roll.utils (RIIR 5). `fixtures/selection.json` is
//! generated by scripts/upstream-oracle/gen-selection.ts.
//!
//! Checked twice: the selection functions on their own, and the playback
//! commands that use them, so `load/next` over HTTP lands where upstream's does.

use ontime_core::command::Command;
use ontime_core::rundown::Rundown;
use ontime_core::runtime::{Playback, Runtime};
use ontime_core::selection::{
    event_at_index, is_loadable, next_playable, next_roll_event, next_with_cue, playable,
    previous_playable, timed,
};
use serde::Deserialize;

const T0: i64 = 1_700_000_000_000;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct CueCase {
    cue: String,
    start: Option<String>,
    start_armed: Option<String>,
    load: Option<String>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct From {
    current: Option<String>,
    next: Option<String>,
    previous: Option<String>,
    roll_next: Option<String>,
    cues: Vec<CueCase>,
}

#[derive(Deserialize)]
struct IndexCase {
    index: usize,
    id: Option<String>,
    loadable: bool,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    rundown: Rundown,
    timed: Vec<String>,
    playable: Vec<String>,
    from: Vec<From>,
    indices: Vec<IndexCase>,
}

#[derive(Deserialize)]
struct Fixture {
    cases: Vec<Case>,
}

fn cases() -> Vec<Case> {
    let fixture: Fixture = serde_json::from_str(include_str!("fixtures/selection.json")).unwrap();
    fixture
        .cases
        .into_iter()
        .map(|mut case| {
            case.rundown.recompute();
            case
        })
        .collect()
}

#[test]
fn the_two_orders_match_upstream() {
    for case in cases() {
        assert_eq!(timed(&case.rundown), case.timed, "{}: timed", case.name);
        assert_eq!(
            playable(&case.rundown),
            case.playable,
            "{}: playable",
            case.name
        );
    }
}

#[test]
fn the_selection_functions_match_upstream() {
    let mut failures = Vec::new();
    for case in cases() {
        let rundown = &case.rundown;
        for from in &case.from {
            let current = from.current.as_deref();
            let at = |what: &str| format!("{} from {current:?}: {what}", case.name);
            let current_index = current.and_then(|id| case.timed.iter().position(|e| e == id));
            let timed_ids: Vec<&str> = case.timed.iter().map(String::as_str).collect();
            let playable_ids: Vec<&str> = case.playable.iter().map(String::as_str).collect();
            let owned = |id: Option<&str>| id.map(str::to_string);

            let mut check = |what: String, ours: Option<String>, want: &Option<String>| {
                if ours != *want {
                    failures.push(format!("{what}: upstream {want:?}, ours {ours:?}"));
                }
            };
            check(
                at("next"),
                owned(next_playable(&playable_ids, current)),
                &from.next,
            );
            check(
                at("previous"),
                owned(previous_playable(&playable_ids, current)),
                &from.previous,
            );
            check(
                at("roll next"),
                owned(next_roll_event(rundown, current)),
                &from.roll_next,
            );
            for cue in &from.cues {
                let pick = |order: &[&str], allow| {
                    owned(next_with_cue(
                        rundown,
                        order,
                        &cue.cue,
                        current_index,
                        allow,
                    ))
                };
                check(
                    at(&format!("start cue {}", cue.cue)),
                    pick(&timed_ids, false),
                    &cue.start,
                );
                check(
                    at(&format!("start armed cue {}", cue.cue)),
                    pick(&timed_ids, true),
                    &cue.start_armed,
                );
                check(
                    at(&format!("load cue {}", cue.cue)),
                    pick(&playable_ids, false),
                    &cue.load,
                );
            }
        }
        for index in &case.indices {
            let timed_ids: Vec<&str> = case.timed.iter().map(String::as_str).collect();
            let ours = event_at_index(&timed_ids, index.index).map(str::to_string);
            if ours != index.id {
                failures.push(format!(
                    "{}: index {}: upstream {:?}, ours {ours:?}",
                    case.name, index.index, index.id
                ));
            }
            let loadable = ours.as_deref().is_some_and(|id| is_loadable(rundown, id));
            if loadable != index.loadable {
                failures.push(format!(
                    "{}: index {} loadable: upstream {}, ours {loadable}",
                    case.name, index.index, index.loadable
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// A runtime with `current` loaded and armed, or nothing loaded.
fn armed(rundown: &Rundown, current: Option<&str>) -> Runtime {
    let mut runtime = Runtime::default();
    if let Some(id) = current {
        assert!(runtime.apply(Command::LoadId(id.to_string()), rundown, T0, 0));
    }
    runtime
}

/// What a command selects from `current`: `None` when it refuses.
fn selects(rundown: &Rundown, mut runtime: Runtime, command: Command) -> Option<String> {
    match runtime.apply(command, rundown, T0, 0) {
        true => runtime.selected_id,
        false => None,
    }
}

#[test]
fn the_playback_commands_land_where_upstream_does() {
    let mut failures = Vec::new();
    for case in cases() {
        let rundown = &case.rundown;
        for from in &case.from {
            let current = from.current.as_deref();
            let mut check = |what: &str, ours: Option<String>, want: &Option<String>| {
                if ours != *want {
                    failures.push(format!(
                        "{} from {current:?}: {what}: upstream {want:?}, ours {ours:?}",
                        case.name
                    ));
                }
            };
            check(
                "load next",
                selects(rundown, armed(rundown, current), Command::LoadNext),
                &from.next,
            );
            check(
                "load previous",
                selects(rundown, armed(rundown, current), Command::LoadPrevious),
                &from.previous,
            );
            for cue in &from.cues {
                let load = Command::LoadCue(cue.cue.clone());
                check(
                    &format!("load cue {}", cue.cue),
                    selects(rundown, armed(rundown, current), load),
                    &cue.load,
                );
                // start allows the armed event itself, which only exists once one is loaded
                let start = Command::StartCue(cue.cue.clone());
                let want = match current {
                    Some(_) => &cue.start_armed,
                    None => &cue.start,
                };
                check(
                    &format!("start cue {}", cue.cue),
                    selects(rundown, armed(rundown, current), start),
                    want,
                );
            }
        }
        for index in &case.indices {
            let want = index.id.clone().filter(|_| index.loadable);
            let ours = selects(
                rundown,
                armed(rundown, None),
                Command::LoadIndex(index.index),
            );
            if ours != want {
                failures.push(format!(
                    "{}: load index {}: upstream {want:?}, ours {ours:?}",
                    case.name, index.index
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn a_skipped_event_cannot_be_loaded_by_id() {
    let case = cases()
        .into_iter()
        .find(|case| case.name == "skipped events")
        .unwrap();
    let mut runtime = Runtime::default();
    assert!(!runtime.apply(Command::LoadId("a".into()), &case.rundown, T0, 0));
    assert_eq!(runtime.playback, Playback::Stop);
    assert!(runtime.apply(Command::LoadId("b".into()), &case.rundown, T0, 0));
}
